<script setup>
import { formatDateTime, formatDate } from "../utils/workflow.js"
import { computed, onMounted, ref } from 'vue'
import { apiGet, apiRequest } from '../services/api.js'
import { useAuthStore } from '../stores/auth.js'
import { label, today } from '../utils.js'
import FormPanel from '../components/FormPanel.vue'
const auth = useAuthStore(), rows = ref([]), selected = ref(null), assignees = ref([]), filter = ref(''), error = ref(''), notice = ref(''), busy = ref(false)
const stages = ['invited', 'interested', 'welcomed', 'participating', 'followup', 'completed', 'opted_out']
const campaigns = computed(() => [...new Map(rows.value.map(r => [r.campaign_id, { id: r.campaign_id, title: r.title }])).values()])
const filtered = computed(() => rows.value.filter(r => !filter.value || Number(r.campaign_id) === Number(filter.value)))
const fields = computed(() => [{ name: 'assigned_to', label: 'Responsável vinculado ao paciente', options: assignees.value.map(u => ({ value: Number(u.id), label: u.name })), default: Number(auth.user.id) }, { name: 'kind', label: 'Próximo passo', options: [{ value: 'contact', label: 'Oferecer contato' }, { value: 'welcome', label: 'Acolhimento' }, { value: 'followup', label: 'Acompanhamento' }] }, { name: 'due_date', label: 'Data prevista', type: 'date', default: today() }, { name: 'administrative_note', label: 'Nota administrativa sem detalhes clínicos', type: 'textarea', max: 1000, optional: true, wide: true }])
async function load() { rows.value = await apiGet('/engagement/pipeline'); if (selected.value) selected.value = rows.value.find(r => Number(r.id) === Number(selected.value.id)) || null }
async function select(row) { busy.value = true; error.value = ''; try { assignees.value = await apiGet(`/engagement/participants/${row.id}/assignees`); selected.value = row } catch (e) { error.value = e.message } finally { busy.value = false } }
async function stage(row, stage) { busy.value = true; error.value = ''; try { await apiRequest(`/engagement/participants/${row.id}`, 'PUT', { stage, version: Number(row.version) }); await load() } catch (e) { error.value = e.message } finally { busy.value = false } }
async function task(data) { busy.value = true; error.value = ''; try { await apiRequest(`/engagement/participants/${selected.value.id}/tasks`, 'POST', data); await load(); notice.value = 'Próximo passo registrado para o responsável.' } catch (e) { error.value = e.message } finally { busy.value = false } }
async function finish(t, status) { busy.value = true; error.value = ''; try { await apiRequest(`/engagement/tasks/${t.id}`, 'PUT', { status, version: Number(t.version), administrative_note: t.administrative_note }); await load() } catch (e) { error.value = e.message } finally { busy.value = false } }
onMounted(async () => { busy.value = true; try { await load() } catch (e) { error.value = e.message } finally { busy.value = false } })
</script>
<template><p class="eyebrow">RELACIONAMENTO E ACOLHIMENTO</p><h1>Um próximo passo claro para cada pessoa</h1><p class="lead">Fila simplificada de campanhas. Apenas pacientes vinculados à sua equipe; informações clínicas permanecem nos módulos assistenciais.</p><p v-if="error" class="alert alert-danger" role="alert">{{ error }}</p><p v-if="notice" class="alert alert-success" role="status">{{ notice }}</p><label for="pipeline-campaign" class="form-label">Campanha</label><select id="pipeline-campaign" v-model="filter" class="form-select mb-4"><option value="">Todas as campanhas vinculadas</option><option v-for="c in campaigns" :key="c.id" :value="c.id">{{ c.title }}</option></select><p v-if="busy">Processando…</p><div class="pipeline-board"><section v-for="s in stages" :key="s" class="pipeline-column"><h2 class="h6">{{ label(s) }} <span class="badge text-bg-light">{{ filtered.filter(r => r.stage === s).length }}</span></h2><article v-for="r in filtered.filter(r => r.stage === s)" :key="r.id" class="card card-body mb-3"><h3 class="h6">{{ r.patient_name }}</h3><p class="small text-secondary">{{ r.title }} · {{ r.cycle_label }}</p><p class="small">{{ r.tasks.filter(t => t.status === 'open').length }} tarefa(s) aberta(s)</p><button class="btn btn-sm btn-outline-success" :disabled="busy" @click="select(r)">Abrir acompanhamento</button></article></section></div><section v-if="selected" class="card card-body mt-4"><div class="d-flex justify-content-between"><div><h2 class="h4">{{ selected.patient_name }}</h2><p>{{ selected.title }} · {{ label(selected.stage) }}</p></div><button class="btn btn-outline-secondary align-self-start" @click="selected = null">Fechar</button></div><div class="d-flex flex-wrap gap-2 mb-4"><button v-for="s in ['welcomed', 'participating', 'followup']" :key="s" class="btn btn-outline-success" :disabled="busy || selected.stage === 'opted_out'" @click="stage(selected, s)">{{ label(s) }}</button></div><p v-if="selected.stage === 'opted_out'" class="alert alert-info">A pessoa optou por não participar agora. Novos contatos da campanha ficam bloqueados até manifestação dela.</p><FormPanel v-else :key="selected.id" :fields="fields" :busy="busy" submit-label="Criar próximo passo" @submit="task" /><h3 class="h5 mt-4">Tarefas e acolhimentos</h3><div v-for="t in selected.tasks" :key="t.id" class="border-top py-3"><strong>{{ label(t.kind) }}</strong> · {{ formatDate(t.due_date) }} · {{ label(t.status) }}<p>{{ t.administrative_note }}</p><div v-if="Number(t.assigned_to) === Number(auth.user.id) && t.status !== 'done'" class="d-flex gap-2"><button class="btn btn-sm btn-success" :disabled="busy" @click="finish(t, 'done')">Concluir tarefa</button><button class="btn btn-sm btn-outline-secondary" :disabled="busy" @click="finish(t, 'deferred')">Registrar adiamento</button></div></div><details class="mt-3"><summary>Histórico do ciclo</summary><p v-for="h in selected.history" :key="h.id" class="small mt-2">{{ formatDateTime(h.created_at) }} · {{ label(h.event_type) }} · responsável #{{ h.author_id }}</p></details></section></template>
